// Zugangsgrenze des Plugins: ausschließlich Mitgliedschaft in der Keycloak-Gruppe
// `rancher-multisite-users`.
//
// Vertrag:
//   - Erlaubt ist genau der Rancher-Principal `keycloakoidc_group://rancher-multisite-users`
//     mit `memberOf === true` (= aktuelle Mitgliedschaft des angemeldeten Users).
//   - KEINE implizite Admin-Freigabe: Rancher-Admins ohne diese Gruppe sind ebenso
//     gesperrt wie Kunden-User. Es gibt hier bewusst keinen Schema-/Rollen-Check.
//   - Exakter Id-Vergleich — keine Substrings, keine Namensheuristik: sonst würde
//     z. B. `keycloakoidc_group://rancher-multisite-users-readonly` mitmatchen.
//   - Fail-closed: jeder Fehlerpfad (API-Fehler, Store nicht bereit, kaputte Antwort)
//     endet bei `false`.
//   - Diese Grenze ist eine UI-Grenze. Die harte Grenze für die eigentlichen
//     Schreiboperationen bleibt Rancher-RBAC auf dem Server.
//
// Autoritätsquelle ist der hier definierte, namespaced Vuex-Store `multisiteAccess`
// — KEIN modul-lokaler Promise-Cache. Ein Cache, der einen Logout überlebt, kann bei
// erneuter Anmeldung desselben Principals ein entzogenes Recht weiter als `true`
// führen; genau das war der Befund C1. Statt eines Caches gibt es hier:
//   - `generation`: wird bei jedem `refresh` und jedem `invalidate` erhöht,
//   - `principalId`: Identitäts-Snapshot der laufenden Prüfung,
//   - eine Gegenprüfung beider Werte VOR jedem Commit und vor jedem Return.
// Überholte oder identitätsfremde Antworten sind damit wirkungslos und liefern `false`.
//
// Das JWT wird NICHT selbst geparst. Rancher normalisiert die Gruppen des Tokens
// bereits zu Principals unter /v3/principals (Norman-Typ `principal`).
//
// Dieses Modul hat bewusst KEINE Imports — es ist damit ohne Bundler direkt unter
// Node testbar (siehe ../tests/).
export const REQUIRED_GROUP = 'rancher-multisite-users';
export const REQUIRED_PRINCIPAL_ID = `keycloakoidc_group://${ REQUIRED_GROUP }`;

export const ACCESS_STORE = 'multisiteAccess';
export const ALLOWED_GETTER = `${ ACCESS_STORE }/allowed`;
export const LOADING_GETTER = `${ ACCESS_STORE }/loading`;
export const EPOCH_GETTER = `${ ACCESS_STORE }/epoch`;

// Reine Entscheidungsfunktion über einer Principal-Liste.
export function hasRequiredGroup(principals: any): boolean {
  if (!Array.isArray(principals)) {
    return false;
  }

  return principals.some((p: any) => p?.id === REQUIRED_PRINCIPAL_ID && p?.memberOf === true);
}

function principalIdOf(rootGetters: any): string {
  const id = rootGetters?.['auth/principalId'];

  return typeof id === 'string' ? id : '';
}

// Der Store als Factory, damit Tests eine frische Instanz bekommen.
export function accessStoreModule() {
  return {
    namespaced: true,

    state: () => ({
      allowed:     false, // fail-closed
      loading:     false,
      generation:  0,
      principalId: '',
    }),

    getters: {
      allowed: (state: any) => state.allowed === true,
      loading: (state: any) => state.loading === true,
      // Identität + Generation in einem Wert: die UI fenced Remote-Ergebnisse damit.
      epoch: (state: any) => `${ state.principalId }#${ state.generation }`,
    },

    mutations: {
      // Start einer Prüfung: erst verweigern, dann prüfen.
      begin(state: any, { principalId, preserveAllowed = false }: any) {
        state.generation += 1;
        if (!preserveAllowed) {
          state.allowed = false;
        }
        state.loading = true;
        state.principalId = principalId;
      },

      // Ergebnis übernehmen — aber nur, wenn es noch zu Identität und Generation
      // passt. Zweite Verteidigungslinie; die Action prüft ebenfalls.
      settle(state: any, { generation, principalId, allowed }: any) {
        if (state.generation !== generation || state.principalId !== principalId) {
          return;
        }
        state.allowed = allowed === true;
        state.loading = false;
      },

      // Logout/Invalidierung: Generation hoch, synchron verweigern. Alles, was
      // noch unterwegs ist, wird dadurch wirkungslos.
      deny(state: any) {
        state.generation += 1;
        state.allowed = false;
        state.loading = false;
        state.principalId = '';
      },
    },

    actions: {
      async refresh({
        state, commit, dispatch, rootGetters,
      }: any, { preserveAllowed = false }: any = {}): Promise<boolean> {
        const principalId = principalIdOf(rootGetters);

        // Ohne bekannte Identität wird nicht einmal gefragt — und nichts erlaubt.
        if (!principalId) {
          commit('deny');

          return false;
        }

        commit('begin', { principalId, preserveAllowed });

        const generation = state.generation;

        try {
          const principals = await dispatch('rancher/findAll', {
            type: 'principal',
            opt:  { url: '/v3/principals', force: true },
          }, { root: true });

          // Gegenprüfung VOR Commit und Return: hat sich Identität oder Generation
          // während des Requests geändert, ist dieses Ergebnis überholt.
          if (state.generation !== generation || principalIdOf(rootGetters) !== principalId) {
            return false;
          }

          const allowed = hasRequiredGroup(principals);

          commit('settle', { generation, principalId, allowed });

          return allowed;
        } catch (e) {
          if (state.generation === generation && principalIdOf(rootGetters) === principalId) {
            commit('settle', { generation, principalId, allowed: false });
          }

          return false;
        }
      },

      invalidate({ commit }: any) {
        commit('deny');
      },

      // Die Shell dispatcht beim Abmelden `<storeName>/onLogout` für jeden
      // Plugin-Store (shell/core/plugin.ts). Das ist der verlässlichste
      // Invalidierungspunkt — und ohne diese Action gäbe es dort bei jedem
      // Logout einen „unknown action type"-Fehler.
      onLogout({ commit }: any) {
        commit('deny');
      },
    },
  };
}

// --- Anbindung an die Extension-API -----------------------------------------

// Wird über `plugin.addStore` aufgerufen. Wichtig: Produkt-Init läuft in der Shell
// VOR der Store-Registrierung (core/extension-manager-impl.js), deshalb stößt die
// Registrierung selbst die erste Prüfung an.
export function registerAccessStore(store: any): void {
  if (!store || typeof store.registerModule !== 'function') {
    return;
  }

  if (typeof store.hasModule !== 'function' || !store.hasModule(ACCESS_STORE)) {
    store.registerModule(ACCESS_STORE, accessStoreModule());
  }

  refreshAccess(store);
}

export function unregisterAccessStore(store: any): void {
  if (!store || typeof store.unregisterModule !== 'function') {
    return;
  }

  // Ein echter Unregister-Fehler darf nicht verschluckt werden: Sonst könnte ein
  // veralteter positiver Store-Zustand eine spätere Neuaktivierung überleben.
  // Ein bereits fehlendes Modul ist dagegen der normale idempotente Fall.
  if (typeof store.hasModule !== 'function' || store.hasModule(ACCESS_STORE)) {
    store.unregisterModule(ACCESS_STORE);
  }
}

// Dispatch-Hüllen: nie eine unbehandelte Rejection erzeugen — die Aufrufer sind
// Nav-Hooks, die die Shell ohne await und teils ohne try/catch aufruft.
export function refreshAccess(store: any): Promise<boolean> {
  return Promise.resolve()
    .then(() => store.dispatch(`${ ACCESS_STORE }/refresh`))
    .then((allowed: any) => allowed === true)
    .catch(() => false);
}

// Erneute Prüfung aus dem bereits sichtbaren Wizard: Die Komponente bleibt
// gemountet, damit sie sich nicht über das Gate selbst in eine Mount-Schleife
// versetzt. `loading=true` sperrt währenddessen sämtliche Epoch-Fences; erst ein
// erfolgreiches Ergebnis gibt Remote-Aktionen wieder frei. Bei Ablehnung setzt
// `settle` allowed=false und der Route-Guard entfernt den Wizard sofort.
export function revalidateAccess(store: any): Promise<boolean> {
  return Promise.resolve()
    .then(() => store.dispatch(`${ ACCESS_STORE }/refresh`, { preserveAllowed: true }))
    .then((allowed: any) => allowed === true)
    .catch(() => false);
}

export function invalidateAccess(store: any): Promise<void> {
  return Promise.resolve()
    .then(() => store.dispatch(`${ ACCESS_STORE }/invalidate`))
    .then(() => undefined)
    .catch(() => undefined);
}

// --- Fencing für Remote-Ergebnisse ------------------------------------------

// Momentaufnahme aus Identität und Generation. Leer, wenn der Store fehlt —
// und eine leere Epoche ist nie gültig.
export function accessEpoch(store: any): string {
  try {
    const epoch = store?.getters?.[EPOCH_GETTER];

    return typeof epoch === 'string' ? epoch : '';
  } catch (e) {
    return '';
  }
}

// Darf das Ergebnis eines Requests übernommen bzw. der nächste Request abgesetzt
// werden? Nur wenn der Zugang JETZT erlaubt ist und weder Identität noch
// Generation seit der Momentaufnahme gewechselt haben.
export function isEpochCurrent(store: any, epoch: string): boolean {
  if (!epoch) {
    return false;
  }

  try {
    return store?.getters?.[ALLOWED_GETTER] === true &&
      store?.getters?.[LOADING_GETTER] !== true &&
      accessEpoch(store) === epoch;
  } catch (e) {
    return false;
  }
}

// Minimale Store-Fassade für API-Helfer. Die Prüfung liegt direkt vor jedem
// einzelnen Dispatch und gilt dadurch auch für interne Folgeaufrufe eines
// Helfers. Bereits gestartete Requests kann sie nicht abbrechen; weitere Requests
// nach einem Epochwechsel werden jedoch sicher vor dem Store gestoppt.
export function fencedStore(store: any, epoch: string, isCurrent: (epoch: string) => boolean) {
  return {
    dispatch: (...args: any[]) => {
      if (!isCurrent(epoch)) {
        return Promise.reject(new Error('Zugang oder Anmeldung hat sich geändert.'));
      }

      return store.dispatch(...args);
    },
  };
}
