export const REQUEST_NAMESPACE = 'cattle-multisite-system';
export const REQUEST_COLLECTION_URL = '/v1/multisite.focusnet.de.multisiteclusterrequests';
export const CUSTOMER_COLLECTION_URL = '/v1/multisite.focusnet.de.multisitecustomers';

export const KUBERNETES_VERSIONS = Object.freeze(['v1.34.4+rke2r1']);
export const SIZE_CLASSES = Object.freeze({
  S: {
    controlPlane: { cpu: 2, memoryGiB: 8, diskGiB: 40 },
    worker: { cpu: 2, memoryGiB: 8, diskGiB: 40, countBerlin1: 0, countBerlin2: 0 },
    controlPlaneIsWorker: true,
  },
  M: {
    controlPlane: { cpu: 4, memoryGiB: 16, diskGiB: 40 },
    worker: { cpu: 4, memoryGiB: 16, diskGiB: 40, countBerlin1: 0, countBerlin2: 0 },
    controlPlaneIsWorker: true,
  },
  L: {
    controlPlane: { cpu: 4, memoryGiB: 16, diskGiB: 40 },
    worker: { cpu: 4, memoryGiB: 16, diskGiB: 40, countBerlin1: 3, countBerlin2: 2 },
    controlPlaneIsWorker: false,
  },
  XL: {
    controlPlane: { cpu: 6, memoryGiB: 26, diskGiB: 40 },
    worker: { cpu: 6, memoryGiB: 26, diskGiB: 40, countBerlin1: 4, countBerlin2: 4 },
    controlPlaneIsWorker: false,
  },
});
export const ZONE_LABEL = /^[a-z0-9]([a-z0-9-]{0,22}[a-z0-9])?$/;

const UUID = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;
const CLUSTER_NAME = /^[a-z0-9]([-a-z0-9]*[a-z0-9])?$/;

function items(response: any): any[] {
  const value = response?.data?.data ?? response?.data ?? response;

  return Array.isArray(value) ? value : [];
}

function requireUuid(value: unknown, label: string): string {
  const candidate = `${ value || '' }`.trim();

  if (!UUID.test(candidate)) {
    throw new Error(`${ label } ist keine gültige UUID.`);
  }

  return candidate;
}

function requireClosedObject(value: unknown, keys: string[], label: string): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${ label } enthält zusätzliche oder fehlende Felder.`);
  }

  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();

  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new Error(`${ label } enthält zusätzliche oder fehlende Felder.`);
  }

  return value as Record<string, unknown>;
}

function requireInteger(value: unknown, label: string, minimum: number, maximum: number): number {
  if (!Number.isInteger(value) || (value as number) < minimum || (value as number) > maximum) {
    throw new Error(`${ label } muss eine Ganzzahl zwischen ${ minimum } und ${ maximum } sein.`);
  }

  return value as number;
}

function requireNodeSizes(value: unknown): Record<string, unknown> {
  const nodeSizes = requireClosedObject(
    value,
    ['controlPlane', 'worker', 'controlPlaneIsWorker'],
    'Node-Größen',
  );
  const controlPlane = requireClosedObject(
    nodeSizes.controlPlane,
    ['cpu', 'memoryGiB', 'diskGiB'],
    'Control-Plane-Größe',
  );
  const worker = requireClosedObject(
    nodeSizes.worker,
    ['cpu', 'memoryGiB', 'diskGiB', 'countBerlin1', 'countBerlin2'],
    'Worker-Größe',
  );

  if (typeof nodeSizes.controlPlaneIsWorker !== 'boolean') {
    throw new Error('Control Planes als Worker muss ein Boolean sein.');
  }

  const result = {
    controlPlane: {
      cpu: requireInteger(controlPlane.cpu, 'Control Plane CPU', 2, 32),
      memoryGiB: requireInteger(controlPlane.memoryGiB, 'Control Plane RAM', 4, 256),
      diskGiB: requireInteger(controlPlane.diskGiB, 'Control Plane Disk', 40, 1000),
    },
    worker: {
      cpu: requireInteger(worker.cpu, 'Worker CPU', 2, 32),
      memoryGiB: requireInteger(worker.memoryGiB, 'Worker RAM', 4, 256),
      diskGiB: requireInteger(worker.diskGiB, 'Worker Disk', 40, 1000),
      countBerlin1: requireInteger(worker.countBerlin1, 'Worker-Anzahl Berlin 1', 0, 10),
      countBerlin2: requireInteger(worker.countBerlin2, 'Worker-Anzahl Berlin 2', 0, 10),
    },
    controlPlaneIsWorker: nodeSizes.controlPlaneIsWorker,
  };

  if (result.worker.countBerlin1 + result.worker.countBerlin2 === 0 && !result.controlPlaneIsWorker) {
    throw new Error('Ohne Berliner Worker müssen die Control Planes auch als Worker genutzt werden.');
  }

  return result;
}

export function isValidNodeSizes(value: unknown): boolean {
  try {
    requireNodeSizes(value);

    return true;
  } catch (_error) {
    return false;
  }
}

function randomUuid(): string {
  const candidate = globalThis?.crypto?.randomUUID?.();

  if (!candidate) {
    throw new Error('Der Browser kann keine sichere Request-ID erzeugen.');
  }

  return candidate;
}

export async function listRequests(store: any): Promise<any[]> {
  return items(await store.dispatch('management/request', {
    url:    REQUEST_COLLECTION_URL,
    method: 'GET',
  }));
}

export async function listCustomers(store: any): Promise<any[]> {
  const result = items(await store.dispatch('management/request', {
    url:    CUSTOMER_COLLECTION_URL,
    method: 'GET',
  }));

  return result.filter((customer) => customer?.spec?.status === 'active');
}

export async function createRequest(
  store: any,
  form: any,
  ids: { requestId?: string; idempotencyKey?: string } = {},
): Promise<any> {
  const customerUuid = requireUuid(form?.customerUuid, 'Kunde');
  const clusterName = `${ form?.clusterName || '' }`.trim();
  const kubernetesVersion = `${ form?.kubernetesVersion || '' }`.trim();
  const nodeSizes = requireNodeSizes(form?.nodeSizes);
  const networkMode = `${ form?.networkMode || 'new' }`.trim();
  const requestId = requireUuid(ids.requestId || randomUuid(), 'Request-ID');
  const idempotencyKey = requireUuid(ids.idempotencyKey || randomUuid(), 'Idempotenzschlüssel');

  if (clusterName.length > 63 || !CLUSTER_NAME.test(clusterName)) {
    throw new Error('Der Clustername muss ein gültiger Kubernetes-Name mit höchstens 63 Zeichen sein.');
  }
  if (!KUBERNETES_VERSIONS.includes(kubernetesVersion)) {
    throw new Error('Die gewählte Kubernetes-Version ist nicht freigegeben.');
  }
  if (networkMode !== 'new' && networkMode !== 'existing') {
    throw new Error('Der Netzwerkmodus ist nicht freigegeben.');
  }

  const spec: Record<string, unknown> = {
    requestId,
    customerUuid,
    clusterName,
    kubernetesVersion,
    nodeSizes,
    networkMode,
    idempotencyKey,
  };

  if (networkMode === 'existing') {
    // Ziel-Zone kommt aus dem Katalog (MultisiteCustomer.spec.routingZones);
    // der Server prüft Eigentum und Slot-Identität erneut fail-closed.
    const fabricVrfId = requireUuid(form?.fabricVrfId, 'Routing-Zone');
    const mspId = Number(form?.mspId);

    if (!Number.isInteger(mspId) || mspId <= 0) {
      throw new Error('Die gewählte Routing-Zone trägt keine gültige MSP-ID.');
    }
    spec.fabricVrfId = fabricVrfId;
    spec.mspId = mspId;
  }

  if (networkMode === 'new') {
    const zoneLabel = `${ form?.zoneLabel || '' }`.trim();

    if (zoneLabel) {
      if (!ZONE_LABEL.test(zoneLabel)) {
        throw new Error('Die Zonen-Bezeichnung darf 1–24 Zeichen aus Kleinbuchstaben, Ziffern und Bindestrichen (nicht am Rand) enthalten.');
      }
      spec.zoneLabel = zoneLabel;
    }
  }

  const data = {
    apiVersion: 'multisite.focusnet.de/v1alpha1',
    kind:       'MultisiteClusterRequest',
    metadata:   {
      name:      `msr-${ requestId }`,
      namespace: REQUEST_NAMESPACE,
    },
    spec,
  };

  return store.dispatch('management/request', {
    url:    REQUEST_COLLECTION_URL,
    method: 'POST',
    data,
  });
}
