<script>
import {
  ALLOWED_GETTER, accessEpoch, fencedStore, isEpochCurrent, revalidateAccess,
} from '../lib/gate';
import {
  KUBERNETES_VERSIONS, SIZE_CLASSES, createRequest, isValidNodeSizes, listCustomers, listRequests,
} from '../lib/requests';

const PHASES = [
  'Pending',
  'Validating',
  'FabricProvisioning',
  'FabricVerified',
  'ClusterProvisioning',
  'ClusterActive',
  'FleetPublishing',
  'Ready',
];
const TERMINAL_PHASES = new Set(['Ready', 'Blocked', 'Failed']);

export default {
  name:   'ProvisionWizard',
  layout: 'plain',

  data() {
    return {
      customers: [],
      requests:  [],
      form: {
        customerUuid:     '',
        clusterName:      '',
        kubernetesVersion: KUBERNETES_VERSIONS[0],
        nodeSizes:         {
          controlPlane: { ...SIZE_CLASSES.M.controlPlane },
          worker: { ...SIZE_CLASSES.M.worker },
          controlPlaneIsWorker: SIZE_CLASSES.M.controlPlaneIsWorker,
        },
        networkMode:      'new',
        zoneLabel:        '',
        fabricVrfId:      '',
      },
      phases:             PHASES,
      kubernetesVersions: KUBERNETES_VERSIONS,
      presets:            Object.keys(SIZE_CLASSES),
      currentRequestId:   '',
      loading:            true,
      submitting:         false,
      error:              '',
      pollTimer:          null,
    };
  },

  computed: {
    allowed() {
      return this.$store.getters[ALLOWED_GETTER] === true;
    },
    selectedCustomer() {
      return this.customers.find((entry) => entry?.spec?.customerUuid === this.form.customerUuid);
    },
    customerZones() {
      const zones = this.selectedCustomer?.spec?.routingZones;

      return Array.isArray(zones) ? zones : [];
    },
    selectedZone() {
      return this.customerZones.find((zone) => zone?.fabricVrfId === this.form.fabricVrfId) || null;
    },
    currentRequest() {
      return this.requests.find((entry) => entry?.spec?.requestId === this.currentRequestId) || null;
    },
    currentPhase() {
      return this.currentRequest?.status?.phase || '';
    },
    currentMessage() {
      return this.currentRequest?.status?.message || '';
    },
    workerCount() {
      return this.form.nodeSizes.worker.countBerlin1 + this.form.nodeSizes.worker.countBerlin2;
    },
    canSubmit() {
      return this.allowed && !this.loading && !this.submitting &&
        this.form.customerUuid && this.form.clusterName &&
        this.form.kubernetesVersion && isValidNodeSizes(this.form.nodeSizes) &&
        (this.form.networkMode !== 'existing' || !!this.selectedZone);
    },
  },

  watch: {
    'form.customerUuid'() {
      // Zonen gehören zum Kunden: Kundenwechsel setzt die Zielwahl zurück.
      this.form.networkMode = 'new';
      this.form.fabricVrfId = '';
    },
    'form.networkMode'(mode) {
      if (mode === 'existing') {
        this.form.zoneLabel = '';
      } else {
        this.form.fabricVrfId = '';
      }
    },
  },

  async mounted() {
    if (!await revalidateAccess(this.$store)) {
      this.loading = false;

      return;
    }

    await this.refresh();
  },

  beforeDestroy() {
    this.stopPolling();
  },

  methods: {
    applyPreset(preset) {
      const nodeSizes = SIZE_CLASSES[preset];

      this.form.nodeSizes = {
        controlPlane: { ...nodeSizes.controlPlane },
        worker: { ...nodeSizes.worker },
        controlPlaneIsWorker: nodeSizes.controlPlaneIsWorker,
      };
    },
    stillCurrent(epoch) {
      return isEpochCurrent(this.$store, epoch);
    },
    requestStore(epoch) {
      return fencedStore(this.$store, epoch, (candidate) => this.stillCurrent(candidate));
    },
    async refresh() {
      const epoch = accessEpoch(this.$store);

      if (!this.stillCurrent(epoch)) {
        return;
      }

      try {
        const store = this.requestStore(epoch);
        const [customers, requests] = await Promise.all([
          listCustomers(store),
          listRequests(store),
        ]);

        if (!this.stillCurrent(epoch)) {
          return;
        }

        this.customers = customers;
        this.requests = requests;
        if (!this.form.customerUuid && customers.length === 1) {
          this.form.customerUuid = customers[0].spec.customerUuid;
        }
        this.error = '';
      } catch (e) {
        if (this.stillCurrent(epoch)) {
          this.error = `Katalog oder Status konnten nicht geladen werden: ${ e?.message || e }`;
        }
      } finally {
        if (this.stillCurrent(epoch)) {
          this.loading = false;
        }
      }
    },
    async submit() {
      this.error = '';
      this.submitting = true;

      try {
        if (!await revalidateAccess(this.$store)) {
          return;
        }

        const epoch = accessEpoch(this.$store);
        const created = await createRequest(this.requestStore(epoch), {
          ...this.form,
          // Die MSP-ID ist die Slot-Identität der gewählten Zone aus dem
          // Katalog; der Server prüft sie gegen den Ziel-VRF.
          mspId: this.selectedZone?.mspId,
        });

        if (!this.stillCurrent(epoch)) {
          return;
        }

        this.currentRequestId = created?.spec?.requestId || created?.data?.spec?.requestId || '';
        await this.refresh();
        this.startPolling();
      } catch (e) {
        this.error = `Die Anforderung wurde nicht angelegt: ${ e?.message || e }`;
      } finally {
        this.submitting = false;
      }
    },
    startPolling() {
      this.stopPolling();
      if (!this.currentRequestId || TERMINAL_PHASES.has(this.currentPhase)) {
        return;
      }
      this.pollTimer = window.setInterval(async () => {
        await this.refresh();
        if (TERMINAL_PHASES.has(this.currentPhase)) {
          this.stopPolling();
        }
      }, 5000);
    },
    stopPolling() {
      if (this.pollTimer) {
        window.clearInterval(this.pollTimer);
        this.pollTimer = null;
      }
    },
    isComplete(phase) {
      const current = PHASES.indexOf(this.currentPhase);

      return current >= PHASES.indexOf(phase);
    },
    customerLabel(customer) {
      const spec = customer?.spec || {};

      return `${ spec.displayName || spec.customerUuid } · Tenant ${ spec.tenantId }`;
    },
    zoneClusters(zone) {
      const clusters = Array.isArray(zone?.clusters) ? zone.clusters : [];

      return clusters.length ? clusters.join(', ') : 'noch ohne Cluster';
    },
    zoneDisplay(zone) {
      const prefix = zone.label ? `${ zone.label } · ` : '';

      return `${ prefix }${ zone.name } · VLAN ${ zone.rzVlan } · ${ this.zoneClusters(zone) }`;
    },
    selectRequest(request) {
      this.currentRequestId = request?.spec?.requestId || '';
      this.startPolling();
    },
  },
};
</script>

<template>
  <main class="multisite-request">
    <header class="hero">
      <div>
        <p class="eyebrow">focusnet Multisite Kubernetes</p>
        <h1>Multisite-Cluster anfordern</h1>
        <p class="lede">
          Der Broker baut Netzwerk, Witness und Cluster in einer kontrollierten Saga.
          Infrastruktur-Zugangsdaten und Adresswerte bleiben vollständig serverseitig.
        </p>
      </div>
      <span class="badge">Nur Multisite-Gruppe</span>
    </header>

    <div
      v-if="error"
      class="notice notice--error"
      role="alert"
    >
      {{ error }}
    </div>

    <section class="panel">
      <h2>Bestellung</h2>
      <div class="form-grid">
        <label>
          Kunde
          <select v-model="form.customerUuid" :disabled="loading || submitting">
            <option value="">– Kunde wählen –</option>
            <option
              v-for="customer in customers"
              :key="customer.spec.customerUuid"
              :value="customer.spec.customerUuid"
            >
              {{ customerLabel(customer) }}
            </option>
          </select>
        </label>
        <label>
          Clustername
          <input
            v-model.trim="form.clusterName"
            maxlength="63"
            placeholder="kunde-multisite-01"
            :disabled="submitting"
          >
        </label>
        <label>
          Kubernetes-Version
          <select v-model="form.kubernetesVersion" :disabled="submitting">
            <option v-for="version in kubernetesVersions" :key="version" :value="version">
              {{ version }}
            </option>
          </select>
        </label>
      </div>
    </section>

    <section class="panel">
      <div class="node-size-heading">
        <div>
          <h2>Node-Größen</h2>
          <p class="node-help">
            Preset wählen oder die Werte passend zur Bestellung anpassen.
          </p>
        </div>
        <fieldset class="preset-row">
          <legend>Vorbelegung</legend>
          <button
            v-for="preset in presets"
            :key="preset"
            type="button"
            class="preset-button"
            :disabled="submitting"
            @click="applyPreset(preset)"
          >
            {{ preset }}
          </button>
        </fieldset>
      </div>

      <div class="node-size-groups">
        <fieldset>
          <legend>Control Plane je Berlin · jeweils 1 Node</legend>
          <div class="node-size-grid">
            <label>
              CPU (2–32)
              <input
                v-model.number="form.nodeSizes.controlPlane.cpu"
                type="number"
                min="2"
                max="32"
                step="1"
                :disabled="submitting"
              >
            </label>
            <label>
              RAM GiB (4–256)
              <input
                v-model.number="form.nodeSizes.controlPlane.memoryGiB"
                type="number"
                min="4"
                max="256"
                step="1"
                :disabled="submitting"
              >
            </label>
            <label>
              Disk GiB (40–1000)
              <input
                v-model.number="form.nodeSizes.controlPlane.diskGiB"
                type="number"
                min="40"
                max="1000"
                step="1"
                :disabled="submitting"
              >
            </label>
          </div>
        </fieldset>

        <fieldset>
          <legend>Worker</legend>
          <div class="node-size-grid">
            <label>
              CPU (2–32)
              <input
                v-model.number="form.nodeSizes.worker.cpu"
                type="number"
                min="2"
                max="32"
                step="1"
                :disabled="submitting"
              >
            </label>
            <label>
              RAM GiB (4–256)
              <input
                v-model.number="form.nodeSizes.worker.memoryGiB"
                type="number"
                min="4"
                max="256"
                step="1"
                :disabled="submitting"
              >
            </label>
            <label>
              Disk GiB (40–1000)
              <input
                v-model.number="form.nodeSizes.worker.diskGiB"
                type="number"
                min="40"
                max="1000"
                step="1"
                :disabled="submitting"
              >
            </label>
            <label>
              Anzahl Berlin 1 (0–10)
              <input
                v-model.number="form.nodeSizes.worker.countBerlin1"
                type="number"
                min="0"
                max="10"
                step="1"
                :disabled="submitting"
              >
            </label>
            <label>
              Anzahl Berlin 2 (0–10)
              <input
                v-model.number="form.nodeSizes.worker.countBerlin2"
                type="number"
                min="0"
                max="10"
                step="1"
                :disabled="submitting"
              >
            </label>
          </div>
        </fieldset>
      </div>

      <label class="checkbox-row">
        <input
          v-model="form.nodeSizes.controlPlaneIsWorker"
          type="checkbox"
          :required="workerCount === 0"
          :disabled="submitting"
        >
        <span>Control Planes auch als Worker nutzen</span>
      </label>
      <p
        v-if="workerCount === 0 && !form.nodeSizes.controlPlaneIsWorker"
        class="notice notice--warning"
        role="alert"
      >
        Ohne separate Worker müssen die Control Planes auch als Worker genutzt werden.
      </p>
    </section>

    <section v-if="selectedCustomer" class="panel">
      <h2>Routing-Zonen</h2>
      <p v-if="!customerZones.length">
        Für diesen Kunden gibt es noch keine aktive Routing-Zone — die Bestellung legt eine neue an.
      </p>
      <div v-else class="site-grid">
        <article v-for="zone in customerZones" :key="zone.fabricVrfId">
          <strong v-if="zone.label">{{ zone.label }}</strong>
          <strong>{{ zone.name }}</strong>
          <span>VLAN {{ zone.rzVlan }} · MSP {{ zone.mspId }}</span>
          <span>{{ zoneClusters(zone) }}</span>
        </article>
      </div>
      <div class="form-grid">
        <label>
          Netzwerkmodus
          <select v-model="form.networkMode" :disabled="submitting">
            <option value="new">Neue Routing-Zone anlegen</option>
            <option value="existing" :disabled="!customerZones.length">
              In bestehende Routing-Zone deployen
            </option>
          </select>
        </label>
        <label v-if="form.networkMode === 'new'">
          Bezeichnung der neuen Zone (optional)
          <input
            v-model.trim="form.zoneLabel"
            type="text"
            maxlength="24"
            placeholder="z. B. sfh-prod oder dev"
            :disabled="submitting"
          >
          <small>1–24 Zeichen: Kleinbuchstaben, Ziffern, Bindestrich. Erscheint im Katalog, als Cluster-Label und als Apstra-Tag; der technische Zonenname bleibt.</small>
        </label>
        <label v-if="form.networkMode === 'existing'">
          Ziel-Routing-Zone
          <select v-model="form.fabricVrfId" :disabled="submitting">
            <option value="">– Routing-Zone wählen –</option>
            <option
              v-for="zone in customerZones"
              :key="zone.fabricVrfId"
              :value="zone.fabricVrfId"
            >
              {{ zoneDisplay(zone) }}
            </option>
          </select>
        </label>
      </div>
      <p v-if="form.networkMode === 'existing'" class="notice">
        Der neue Cluster teilt sich Routing-Domäne und Adressraum mit den bestehenden
        Clustern dieser Zone (z.&nbsp;B. gemeinsame Dev- oder Prod-Zone). VIP und Dienste
        bleiben clustereigen; die Zuordnung wird serverseitig gegen Eigentum und
        Slot-Identität geprüft.
      </p>
    </section>

    <section class="panel">
      <h2>Feste Standorte</h2>
      <div class="site-grid">
        <article>
          <strong>Berlin 1</strong>
          <span>Harvester · 1 Control Plane · {{ form.nodeSizes.worker.countBerlin1 }} Worker</span>
        </article>
        <article>
          <strong>Berlin 2</strong>
          <span>Harvester · 1 Control Plane · {{ form.nodeSizes.worker.countBerlin2 }} Worker</span>
        </article>
        <article>
          <strong>Hannover-Witness</strong>
          <span>vSphere · ausschließlich etcd · fest 4 CPU / 8 GiB RAM / 40 GiB Disk</span>
        </article>
      </div>
      <div class="network-summary">
        <strong>Netzwerk automatisch</strong>
        <span v-if="form.networkMode === 'existing'">
          Der Cluster wird in die gewählte Routing-Zone
          {{ selectedZone ? selectedZone.name : '' }} gehängt; VIP-Übergabe und
          Dienste werden serverseitig ergänzt.
        </span>
        <span v-else>VRF, VLAN, VNI, Standortnetze und DCI-Routen werden serverseitig aus Pool 13 und Pool 17 vergeben.</span>
      </div>
    </section>

    <section class="panel review">
      <div>
        <h2>Prüfen und starten</h2>
        <p v-if="selectedCustomer" class="review-summary">
          {{ selectedCustomer.spec.displayName }} · {{ form.clusterName || 'Clustername fehlt' }}
          · Control Plane je Berlin: 1 × {{ form.nodeSizes.controlPlane.cpu }} CPU /
          {{ form.nodeSizes.controlPlane.memoryGiB }} GiB RAM /
          {{ form.nodeSizes.controlPlane.diskGiB }} GiB Disk
          · Worker: Berlin 1 {{ form.nodeSizes.worker.countBerlin1 }} ×, Berlin 2
          {{ form.nodeSizes.worker.countBerlin2 }} ×, je {{ form.nodeSizes.worker.cpu }} CPU /
          {{ form.nodeSizes.worker.memoryGiB }} GiB RAM / {{ form.nodeSizes.worker.diskGiB }} GiB Disk
          · Control Planes als Worker: {{ form.nodeSizes.controlPlaneIsWorker ? 'ja' : 'nein' }}
          · {{ form.networkMode === 'existing' ? `Zone ${ selectedZone ? selectedZone.name : 'fehlt' }` : `neue Routing-Zone${ form.zoneLabel ? ` „${ form.zoneLabel }“` : '' }` }}
        </p>
        <p v-else>Bitte zuerst einen freigegebenen Kunden wählen.</p>
      </div>
      <button class="primary" :disabled="!canSubmit" @click="submit">
        {{ submitting ? 'Anforderung wird angelegt …' : 'Multisite-Cluster anfordern' }}
      </button>
    </section>

    <section v-if="requests.length" class="panel">
      <h2>Vorhandene Anforderungen</h2>
      <div class="request-list">
        <button
          v-for="request in requests"
          :key="request.metadata.uid || request.spec.requestId"
          type="button"
          :class="{ selected: currentRequestId === request.spec.requestId }"
          @click="selectRequest(request)"
        >
          <span>{{ request.spec.clusterName }}</span>
          <strong>{{ request.status && request.status.phase || 'Pending' }}</strong>
        </button>
      </div>
    </section>

    <section v-if="currentRequest" class="panel">
      <div class="status-heading">
        <div>
          <p class="eyebrow">Request {{ currentRequest.spec.requestId }}</p>
          <h2>Bereitstellungsstatus</h2>
        </div>
        <span class="phase">{{ currentPhase }}</span>
      </div>
      <ol class="timeline">
        <li
          v-for="phase in phases"
          :key="phase"
          :class="{ complete: isComplete(phase), current: currentPhase === phase }"
        >
          <span class="dot" />
          <span>{{ phase }}</span>
        </li>
      </ol>
      <p v-if="currentMessage" class="notice">{{ currentMessage }}</p>
    </section>
  </main>
</template>

