import { importTypes } from '@rancher/auto-import';
import { IPlugin } from '@shell/core/types';
import GateGuard from './components/GateGuard.vue';
import {
  ACCESS_STORE, registerAccessStore, unregisterAccessStore, refreshAccess, invalidateAccess,
} from './lib/gate';

export default function (plugin: IPlugin): void {
  importTypes(plugin);

  plugin.metadata = require('./package.json');

  plugin.addProduct(require('./product'));

  // Autoritätsquelle für die Sichtbarkeit: der namespaced Plugin-Store. Die Shell
  // registriert Plugin-Stores NACH dem Produkt-Init, deshalb stößt
  // registerAccessStore die erste Prüfung selbst an.
  plugin.addStore(
    ACCESS_STORE,
    () => (store: any) => registerAccessStore(store),
    (store: any) => unregisterAccessStore(store),
  );

  // Identitätswechsel ohne Full Reload (Abmelden von der Index-Route navigiert nur
  // per Router): beim Abmelden sofort verweigern, bei der Anmeldung neu prüfen.
  plugin.addNavHooks({
    onLogout: (store: any) => invalidateAccess(store),
    onLogin:  (store: any) => refreshAccess(store).then(() => undefined),
  });

  // BEIDE Routen erben dieselbe Prüfung: Route-Komponente ist GateGuard, nicht der
  // Wizard. Direkte URLs (auch von Nicht-Mitgliedern gebookmarkt) laden damit keine
  // Kunden- oder Requestdaten — der Wizard wird erst nach bestätigter
  // Gruppen-Mitgliedschaft überhaupt instanziiert.
  plugin.addRoute({
    name:      'multisite-cluster-provisioner',
    path:      '/multisite-cluster-provisioner',
    component: GateGuard,
    meta:      { product: 'multisite-cluster-provisioner' },
  });

  // Cluster-scoped Route (Parität mit cloud-services-marketplace) — damit `to` auch
  // im Cluster-Kontext (/c/:cluster/…) auflöst und nicht ins Leere zeigt.
  plugin.addRoute({
    name:      'c-cluster-multisite-cluster-provisioner',
    path:      '/c/:cluster/multisite-cluster-provisioner',
    component: GateGuard,
    meta:      { product: 'multisite-cluster-provisioner' },
  });
}
